#!/usr/bin/env python3

import urllib.request
import urllib.error

def check_server():
    try:
        response = urllib.request.urlopen('http://localhost:4000/debug_ui.html')
        if response.getcode() == 200:
            print("SUCCESS: Server is running and debug_ui.html is accessible")
            print(f"Content length: {len(response.read())} bytes")
        else:
            print(f"UNEXPECTED: Server responded with status code {response.getcode()}")
    except urllib.error.URLError as e:
        print(f"ERROR: Server is not accessible - {e}")
        print("Please start the server with: python3 -m http.server 4000")
    except Exception as e:
        print(f"UNEXPECTED ERROR: {e}")

if __name__ == "__main__":
    check_server()

import subprocess
import sys

def run_python_script(script_path):
    try:
        result = subprocess.run([sys.executable, script_path], 
                              capture_output=True, text=True, timeout=30)
        return {
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        }
    except subprocess.TimeoutExpired:
        return {'error': 'Script execution timed out'}
    except Exception as e:
        return {'error': str(e)}

if __name__ == "__main__":
    if len(sys.argv) > 1:
        script_path = sys.argv[1]
        result = run_python_script(script_path)
        print(result)
    else:
        print("Usage: python run_script.py <script_path>")

